def posicao_mru(x0_m, v_m_s, t_s):
    if t_s < 0:
        raise ValueError("Tempo deve ser não negativo")
    return x0_m + v_m_s * t_s
assert posicao_mru(1,2,3) == 7
assert posicao_mru(2,-3,2) == -4
assert posicao_mru(5,8,0) == 5
try:
    posicao_mru(0,1,-1)
except ValueError:
    pass
else:
    raise AssertionError("Tempo negativo deve ser rejeitado")
